  "All conversions": "Alle Umwandlungen",
  "Any language, on this phone. Numbers, names and codes can't be changed; every part is checked, and anything doubtful is marked.": "Jede Sprache, auf diesem Handy. Zahlen, Namen und Codes bleiben unverändert; jeder Teil wird geprüft, und alles Zweifelhafte wird markiert.",
