  "Exchange rates": "Wechselkurse",
  "never": "nie",
  "Studio draws pictures with the phone's own chip — it works in the Android app.": "Studio malt Bilder mit dem eigenen Chip des Handys – das funktioniert in der Android-App.",
  "Steps": "Schritte",
  "Starting Python…": "Python startet…",
  "Code that is tested before you get it": "Code, der getestet wird, bevor du ihn bekommst",
  "The model writes the program and its tests, the phone runs them, and any error goes straight back to the model to fix — until the tests pass. Offline, in a locked sandbox.": "Das Modell schreibt das Programm und seine Tests, das Handy führt sie aus, und jeder Fehler geht direkt zur Korrektur zurück ans Modell – bis die Tests bestehen. Offline, in einer abgeschotteten Sandbox.",
  "What should it do? e.g. “A function that splits a restaurant bill between friends, with the tip”": "Was soll es tun? z. B. „Eine Funktion, die eine Restaurantrechnung mit Trinkgeld unter Freunden aufteilt“",
  "Web page": "Webseite",
  "Build & test": "Bauen & testen",
  "The program and its tests appear here": "Das Programm und seine Tests erscheinen hier",
  "Each step, the code, a live preview for web pages, and whether the tests passed.": "Jeder Schritt, der Code, eine Live-Vorschau für Webseiten und ob die Tests bestanden haben.",
