  "= instant on-device scaffolding.": "= sofortiges Gerüst auf dem Gerät.",
  "= the model rethinks and rephrases your prompt.": "= das Modell durchdenkt deinen Prompt neu und formuliert ihn um.",
  "Tailored for": "Zugeschnitten auf",
  "Write a rough prompt, then hit": "Schreib einen groben Prompt und tipp dann auf",
  "to see the model rethink it — or Structure for an instant offline version.": "damit das Modell ihn neu durchdenkt – oder auf Struktur für eine sofortige Offline-Version.",
  "Your new prompt": "Dein neuer Prompt",
  "Paste a long, wordy prompt — AI Compress will think and shrink it.": "Füg einen langen, wortreichen Prompt ein – KI-Kürzen denkt nach und macht ihn kleiner.",
  "Chat history": "Chatverlauf",
  "Paste the earlier messages — anything already established gets dropped.": "Füg die früheren Nachrichten ein – alles, was schon geklärt ist, fliegt raus.",
