  "fits · {p}% of the window": "passt · {p}% des Fensters",
  "A quarter of the window is held back for the answer — a prompt that exactly fills the context leaves no room to reply.": "Ein Viertel des Fensters bleibt für die Antwort frei – ein Prompt, der den Kontext genau füllt, lässt keinen Platz zum Antworten.",
  "Port context to": "Kontext übertragen an",
