  "Set the rules": "Regeln festlegen",
  "Totals, VAT, links between tables, required fields.": "Summen, MwSt., Verknüpfungen zwischen Tabellen, Pflichtfelder.",
  "Pick how it looks": "Aussehen wählen",
  "On a phone and on a computer — then share it with your team as one app file.": "Auf dem Handy und am Computer – dann teil es mit deinem Team als eine App-Datei.",
  "Build your own business system": "Bau dein eigenes Business-System",
  "For your company, on your phone — no code, and it works without internet.": "Für deine Firma, auf deinem Handy – ohne Code, und es funktioniert ohne Internet.",
  "Got it": "Verstanden",
