  "Free: keep and search everything. Pro: it files each item by itself (title, summary, tags), reads your photos and answers questions from your Mind.": "Gratis: alles behalten und durchsuchen. Pro: sortiert jeden Eintrag selbst ein (Titel, Zusammenfassung, Tags), liest deine Fotos und beantwortet Fragen aus deinem Mind.",
