  "What stands out": "Was auffällt",
  "Every figure here is one Yusr calculated — the model may not produce a new number.": "Jede Zahl hier hat Yusr berechnet – das Modell darf keine neue Zahl erzeugen.",
  "What the AI is allowed to see": "Was die KI sehen darf",
