  "Only download videos you have the right to keep.": "Lade nur Videos herunter, die du behalten darfst.",
  "The clipboard is empty — copy the video's link first": "Die Zwischenablage ist leer – kopiere zuerst den Link des Videos",
  "Long-press the box and choose Paste": "Halte das Feld gedrückt und wähle „Einfügen“",
  "That isn't a link. Copy the video's link (it starts with https://) and paste it here.": "Das ist kein Link. Kopiere den Link des Videos (er beginnt mit https://) und füge ihn hier ein.",
  "{site} doesn't allow its videos to be downloaded, so Attune can't save them (Google Play removes apps that do). Links that work: direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons, and pages that show a plain video file.": "{site} erlaubt keine Downloads seiner Videos, daher kann Attune sie nicht speichern (Google Play entfernt Apps, die das tun). Diese Links funktionieren: direkte Videolinks, Google Drive, Dropbox, archive.org, Wikimedia Commons und Seiten mit einer einfachen Videodatei.",
  "a streaming service": "ein Streamingdienst",
  "this site": "diese Website",
  "That's a live-stream link (.m3u8) — it's streamed in pieces and can't be saved as one file.": "Das ist ein Livestream-Link (.m3u8) – er wird in Stücken gestreamt und kann nicht als eine Datei gespeichert werden.",
  "Downloading works in the Android app.": "Herunterladen funktioniert in der Android-App.",
  "Google Drive didn't give the file — make sure it's shared as \"Anyone with the link\".": "Google Drive hat die Datei nicht freigegeben – stell sicher, dass sie für „Jeder mit dem Link“ geteilt ist.",
  "This page plays a {site} video, which can't be downloaded.": "Diese Seite spielt ein Video von {site} ab, das sich nicht herunterladen lässt.",
  "This page streams its video in pieces (HLS), which can't be saved as one file.": "Diese Seite streamt ihr Video in Stücken (HLS), es kann nicht als eine Datei gespeichert werden.",
  "No downloadable video was found on that page.": "Auf dieser Seite wurde kein herunterladbares Video gefunden.",
