  "install before you fly": "vor dem Flug installieren",
  "Some of these can't be installed or signed up for once you're in the country — do it while you still have your home connection.": "Manche davon kann man im Land nicht mehr installieren oder sich nicht mehr registrieren – erledige das, solange du noch dein Netz von zu Hause hast.",
