  "e.g. the taxi driver won't turn the meter on, what do I say? / is this price fair for a carpet? / can I drink the tap water?": "z. B. der Taxifahrer schaltet das Taxameter nicht ein – was sage ich? / ist der Preis für diesen Teppich fair? / kann ich das Leitungswasser trinken?",
  "It knows how things actually work here — fair prices, common overcharges, what's rude. It will tell you when something needs live data it can't have offline.": "Es weiß, wie die Dinge hier wirklich laufen – faire Preise, übliche Abzocke, was unhöflich ist. Es sagt dir, wenn etwas Live-Daten braucht, die es offline nicht haben kann.",
