  "This looks like medical, legal or safety content. The original document governs — this is a reading aid, not a substitute for it.": "Das sieht nach medizinischem, rechtlichem oder Sicherheitsinhalt aus. Maßgeblich ist das Originaldokument – dies ist eine Lesehilfe, kein Ersatz dafür.",
