  "Choose your plan": "Wähle deinen Tarif",
  "Everything runs on your device, so nothing here is metered by a server. Free gives you 15 runs a day; Pro removes the limit and adds memory, commitments and your own vocabulary. Regional pricing at checkout (EGP and local currencies).": "Alles läuft auf deinem Gerät, daher zählt hier kein Server mit. Gratis hast du 15 Durchläufe pro Tag; Pro hebt das Limit auf und bringt Gedächtnis, Zusagen und deinen eigenen Wortschatz dazu. Regionale Preise an der Kasse (EGP und Landeswährungen).",
