  "— a 3 GB model usually takes 10–40 s.": "– ein 3-GB-Modell braucht meist 10–40 s.",
  "This model is large for this phone. It works, but answers come slowly and the phone gets warm. For quick, smooth answers use Qwen 3.5 4B — same Arabic, reads photos, about 3× faster.": "Dieses Modell ist groß für dieses Handy. Es funktioniert, aber Antworten kommen langsam und das Handy wird warm. Für schnelle, flüssige Antworten nimm Qwen 3.5 4B – gleiches Arabisch, liest Fotos, etwa 3× schneller.",
