  "INT4 KV cache + sliding-window eviction, so long conversations don't grow unbounded.": "INT4-KV-Cache + Sliding-Window-Verdrängung, damit lange Gespräche nicht unbegrenzt wachsen.",
  "Storage:": "Speicher:",
  "Compute": "Rechenleistung",
  "Prefill runs where compute is fastest, decode where bandwidth is. Using both raises usable bandwidth ~43 → 59 GB/s.": "Prefill läuft dort, wo die Rechenleistung am höchsten ist, Decode dort, wo die Bandbreite am höchsten ist. Beides zusammen erhöht die nutzbare Bandbreite von ~43 auf 59 GB/s.",
  "Task adapters": "Aufgaben-Adapter",
  "Small fine-tunes for each job — this is what makes a phone-sized model punch above its weight. Loaded over the base model, a few MB each.": "Kleine Feinabstimmungen für jede Aufgabe – dadurch leistet ein Modell in Handygröße mehr, als man erwartet. Sie werden über das Basismodell geladen und sind je ein paar MB groß.",
