  "Turns logged downtime into a figure you can put in front of management.": "Macht aus erfassten Stillstandszeiten eine Zahl, die du der Geschäftsführung vorlegen kannst.",
  "Reporting rules": "Berichtsregeln",
  "e.g. every incident must state whether work was stopped; always record permit number": "z. B. jeder Vorfall muss angeben, ob die Arbeit gestoppt wurde; Freigabenummer immer erfassen",
  "This is added to every field document — and it's also what your own adapter trains on, so the model learns your operation, not a generic one.": "Das wird jedem Feldbericht hinzugefügt – und es ist auch das, womit dein eigener Adapter trainiert, damit das Modell deinen Betrieb lernt und keinen allgemeinen.",
