  "days, so predictions are rough. If cycles are often very irregular, it's worth mentioning to a doctor.": "Tage, die Vorhersagen sind also ungenau. Wenn deine Zyklen oft sehr unregelmäßig sind, solltest du das bei einem Arzt ansprechen.",
