  "Backup & restore": "Sicherung & Wiederherstellung",
  "Everything in Attune lives only on this phone. A backup is one file, locked with your password, that you can keep anywhere.": "Alles in Attune liegt nur auf diesem Handy. Eine Sicherung ist eine einzige Datei, mit deinem Passwort verschlüsselt, die du überall aufbewahren kannst.",
