  "Notifications are off for Attune — tap to allow them, or reminders can't appear.": "Benachrichtigungen sind für Attune aus – tippe, um sie zu erlauben, sonst können Erinnerungen nicht erscheinen.",
  "Reminders may come up to 10 minutes late. Tap to allow “Alarms & reminders” for Attune so they ring on the minute.": "Erinnerungen können bis zu 10 Minuten zu spät kommen. Tippe, um „Wecker & Erinnerungen“ für Attune zu erlauben, damit sie auf die Minute klingeln.",
  "In the browser reminders are only listed — the Android app rings them.": "Im Browser werden Erinnerungen nur aufgelistet – die Android-App lässt sie klingeln.",
