  "I couldn't make every test pass yet — here is the closest version; tap “Test & fix in Code” to keep going.": "Ich konnte noch nicht alle Tests zum Bestehen bringen – hier ist die nächstbeste Version; tippe auf „In Code testen & beheben“, um weiterzumachen.",
  "Working it out as a program…": "Wird als Programm ausgerechnet…",
  "Fixing the program and running it again…": "Programm wird repariert und erneut ausgeführt…",
