  "FLUX.2 klein 4B · high quality": "FLUX.2 klein 4B · hohe Qualität",
  "The best pictures this phone can make: the 8-bit build of FLUX.2 klein — finer detail, cleaner faces, hands and text. Also edits your photos by instruction.": "Die besten Bilder, die dieses Handy erzeugen kann: der 8-Bit-Build von FLUX.2 klein – feinere Details, sauberere Gesichter, Hände und Text. Bearbeitet auch deine Fotos nach Anweisung.",
  "That file is too large (15 MB at most)": "Die Datei ist zu groß (höchstens 15 MB)",
  "What's in this file? Summarise what matters.": "Was steht in dieser Datei? Fasse das Wichtige zusammen.",
  "Checked — the reviewer fixed a mistake": "Geprüft – der Prüfer hat einen Fehler korrigiert",
