  "This is the design. Tap any table or field name to rename it — you can change everything else after creating it.": "Das ist der Entwurf. Tippe auf einen Tabellen- oder Feldnamen, um ihn umzubenennen – alles andere kannst du nach dem Erstellen ändern.",
