  "Pay with InstaPay, Vodafone Cash or a card, and send this code with it. You'll get your activation code back, made for this phone.": "Zahle mit InstaPay, Vodafone Cash oder Karte und sende diesen Code mit. Du bekommst deinen Aktivierungscode zurück, passend für dieses Handy.",
