  "Drawing on the GPU failed twice, so Attune switched Studio to the CPU. ": "Das Zeichnen auf der GPU ist zweimal fehlgeschlagen, deshalb hat Attune Studio auf die CPU umgestellt. ",
  "The GPU driver stalled twice while loading the picture model, so Attune switched Studio to the CPU (you can try the GPU again below).": "Der GPU-Treiber hat beim Laden des Bildmodells zweimal gehangen, deshalb hat Attune Studio auf die CPU umgestellt (unten kannst du die GPU erneut versuchen).",
