  "Search a place and tap “Save this place” — saved places work with no signal.": "Suche einen Ort und tippe auf „Diesen Ort speichern“ – gespeicherte Orte funktionieren ohne Empfang.",
  "Download a whole country once: every road, building, place and shop, and search — all with no signal. A new version is built every week from OpenStreetMap; the app tells you when one is ready.": "Lade ein ganzes Land einmal herunter: jede Straße, jedes Gebäude, jeden Ort und jedes Geschäft, plus Suche – alles ohne Empfang. Jede Woche wird aus OpenStreetMap eine neue Version erstellt; die App sagt dir, wenn eine bereit ist.",
