  "With signal, every country here shows online without downloading — every street, compound and place. Download only to use it with no signal.": "Mit Empfang wird jedes Land hier online angezeigt, ohne Download – jede Straße, Wohnanlage und jeder Ort. Lade nur herunter, um sie ohne Empfang zu nutzen.",
  "This map is not published yet": "Diese Karte ist noch nicht veröffentlicht",
