  "Visa required. e-Visa is available only to applicants under 20 or over 45; everyone else applies at a consulate.": "Visum nötig. Das E-Visum gibt es nur für Antragsteller unter 20 oder über 45; alle anderen beantragen es beim Konsulat.",
  "Visa-free, 90 days in any 180.": "Visumfrei, 90 Tage innerhalb von 180.",
