  "Visa-free for UK, US, Canada and Australia.": "Visumfrei für UK, USA, Kanada und Australien.",
  "e-Visa online. Visa-free if you already hold a valid EU, US, UK or GCC visa or residence permit.": "E-Visum online. Visumfrei, wenn du schon ein gültiges Visum oder eine Aufenthaltserlaubnis der EU, USA, des UK oder der GCC hast.",
