  "Schengen visa required for most nationalities.": "Schengen-Visum für die meisten Staatsangehörigkeiten nötig.",
  "e-Visa online — and you must arrive through OR Tambo International.": "E-Visum online – und du musst über den Flughafen OR Tambo International einreisen.",
  "Visa required. An e-Visa is possible if you hold a valid EU, US, UK, Canadian, Australian, Japanese or NZ visa.": "Visum nötig. Ein E-Visum ist möglich, wenn du ein gültiges Visum der EU, USA, des UK, Kanadas, Australiens, Japans oder Neuseelands hast.",
  "e-Visa for many nationalities.": "E-Visum für viele Staatsangehörigkeiten.",
  "Conditional. Visa on arrival applies to organised groups of 10 or more; individuals normally need a visa in advance.": "Mit Bedingungen. Visum bei Ankunft gilt für organisierte Gruppen ab 10 Personen; Einzelreisende brauchen normalerweise vorab ein Visum.",
