  "Cyprus visa required (Cyprus is in the EU but not in Schengen). Holders of a valid Schengen double or multiple-entry visa can often enter — confirm with the embassy.": "Zypern-Visum nötig (Zypern ist in der EU, aber nicht im Schengen-Raum). Inhaber eines gültigen Schengen-Visums für zwei- oder mehrfache Einreise dürfen oft einreisen – bei der Botschaft bestätigen.",
