  "per passenger": "pro Person",
  "Ask the airline for the reason: weather or an air-traffic strike would cancel it; a technical fault or crew shortage would not.": "Frag die Airline nach dem Grund: Wetter oder ein Fluglotsenstreik würden es ausschließen, ein technischer Defekt oder Personalmangel nicht.",
  "Write the claim": "Forderung schreiben",
