  "Worked out from the published rules (EU 261, UK 261, Canada's APPR). Airlines sometimes refuse at first — a polite second letter or the national enforcement body usually settles it.": "Berechnet nach den veröffentlichten Regeln (EU 261, UK 261, Kanadas APPR). Airlines lehnen manchmal zuerst ab – ein höflicher zweiter Brief oder die nationale Durchsetzungsstelle klärt es meist.",
