  "How late did you arrive at your destination (hours)?": "Wie spät bist du am Ziel angekommen (Stunden)?",
  "Over 3,500 km with a 3–4 hour delay: the airline may halve it.": "Über 3.500 km mit 3–4 Stunden Verspätung: Die Airline darf halbieren.",
  "Told 7–13 days ahead: not owed if they offered a flight leaving at most 2 h earlier and arriving at most 4 h later than yours.": "7–13 Tage vorher informiert: kein Anspruch, wenn ein Flug angeboten wurde, der höchstens 2 Std. früher startet und höchstens 4 Std. später ankommt als deiner.",
  "Told under 7 days ahead: not owed only if they offered a flight leaving at most 1 h earlier and arriving at most 2 h later than yours.": "Weniger als 7 Tage vorher informiert: nur kein Anspruch, wenn ein Flug angeboten wurde, der höchstens 1 Std. früher startet und höchstens 2 Std. später ankommt als deiner.",
  "Owed when the delay was within the airline's control and not for safety. Claim within 1 year.": "Anspruch, wenn die Verspätung in der Verantwortung der Airline lag und nicht sicherheitsbedingt war. Innerhalb von 1 Jahr fordern.",
