  "Running on the NPU ({d}).": "Läuft auf der NPU ({d}).",
  "Runs the model on the Snapdragon NPU (Hexagon): much cooler, often faster at reading. Works best with Core Max (8-bit). Switches itself back to the CPU if anything goes wrong.": "Lässt das Modell auf der Snapdragon-NPU (Hexagon) laufen: viel kühler, beim Lesen oft schneller. Am besten mit Core Max (8-Bit). Wechselt von selbst zurück zur CPU, wenn etwas schiefgeht.",
  "This phone's NPU could not be used by the engine — Attune stays on the CPU.": "Die NPU dieses Handys konnte von der Engine nicht genutzt werden – Attune bleibt auf der CPU.",
  "Last time, starting on the NPU closed the app. Attune is back on the CPU; you can try it again in Engine → Speed.": "Beim letzten Mal hat der Start auf der NPU die App geschlossen. Attune ist wieder auf der CPU; du kannst es unter Engine → Tempo erneut versuchen.",
  "You have {b}. Until {d} ({n} days) these are due: {t}. What is left, shared over the days, is what you can spend each day.": "Du hast {b}. Bis {d} ({n} Tage) ist das fällig: {t}. Was übrig bleibt, auf die Tage verteilt, kannst du pro Tag ausgeben.",
  "Nothing due before then.": "Bis dahin ist nichts fällig.",
  "Tip: add your salary as a repeating income in Money, and this counts until payday.": "Tipp: Trag dein Gehalt als wiederkehrende Einnahme in Geld ein, dann zählt es bis zum Zahltag.",
