  "Mission started — Attune works on it every day": "Mission gestartet – Attune arbeitet jeden Tag daran",
  "Say a goal with a deadline. Attune works on it every day: it reads your money, food and Scout ads, gives your real chance, and the one step for today.": "Nenne ein Ziel mit Frist. Attune arbeitet jeden Tag daran: Es liest dein Geld, dein Essen und Scout-Anzeigen, zeigt deine echte Chance und den einen Schritt für heute.",
  "e.g. «عايز أوفر 60 ألف قبل يونيو»": "z. B. «عايز أوفر 60 ألف قبل يونيو»",
  "Save {t}": "{t} sparen",
  "Lose {t} kg": "{t} kg abnehmen",
  "Buy it for {t} or less": "Für {t} oder weniger kaufen",
  "by {d}": "bis {d}",
  "add a date (e.g. by June)": "füge ein Datum hinzu (z. B. bis Juni)",
  "Say a number and a date: save 60,000 by June · lose 6 kg before 20 January · buy … under 900k by 1 December · spend no more than 3,000 on food this month · pay off Ahmed's debt by December · finish the Turkish course by December.": "Nenne eine Zahl und ein Datum: 60.000 bis Juni sparen · 6 kg vor dem 20. Januar abnehmen · … unter 900k bis 1. Dezember kaufen · diesen Monat höchstens 3.000 für Essen ausgeben · Ahmeds Schulden bis Dezember abzahlen · den Türkischkurs bis Dezember beenden.",
  "Start the mission": "Mission starten",
  "Your money missions need {a} a month together, but you keep about {b}. Pause one, or move a date.": "Deine Geld-Missionen brauchen zusammen {a} pro Monat, aber du behältst etwa {b}. Pausiere eine oder verschiebe ein Datum.",
  "No missions yet. Start one above — a saving goal, a weight goal, something to buy, a spending limit, a debt or a course.": "Noch keine Missionen. Starte oben eine – ein Sparziel, ein Gewichtsziel, etwas zum Kaufen, ein Ausgabenlimit, Schulden oder einen Kurs.",
  "A goal with a date — Attune works on it every day": "Ein Ziel mit Datum – Attune arbeitet jeden Tag daran",
  "{c}% chance": "{c} % Chance",
  "A goal with a date — Attune works on it every day and shows your real chance": "Ein Ziel mit Datum – Attune arbeitet jeden Tag daran und zeigt deine echte Chance",
  "Where": "Wo",
  "Every tool in three steps, with a drawing of its screen — and a plan to make Attune part of your day.": "Jedes Tool in drei Schritten, mit einer Zeichnung seines Bildschirms – und ein Plan, wie Attune Teil deines Tages wird.",
  "Sync": "Sync",
  "Backup & sync": "Backup & Sync",
  "Synced — {a} new, {c} updated. Reopening…": "Synchronisiert – {a} neu, {c} aktualisiert. Wird neu geöffnet …",
  "Waiting for the other device…": "Warte auf das andere Gerät …",
  "Merging…": "Führe zusammen …",
  "Locking and sending…": "Verschlüssle und sende …",
