  "Locking and uploading…": "Verschlüssle und lade hoch …",
  "Type the address shown on the other device, like 192.168.1.20:41873": "Gib die Adresse ein, die das andere Gerät zeigt, z. B. 192.168.1.20:41873",
  "The code has 8 letters and numbers": "Der Code hat 8 Buchstaben und Ziffern",
  "Set your sync passphrase first — the same on every device.": "Lege zuerst deine Sync-Passphrase fest – auf jedem Gerät dieselbe.",
  "Keep your phone and computer (or two phones) the same. The data is locked before it leaves this device; what you delete on one is deleted on the other, nothing else is lost.": "Halte Handy und Computer (oder zwei Handys) gleich. Die Daten werden verschlüsselt, bevor sie dieses Gerät verlassen; was du auf einem löschst, wird auf dem anderen gelöscht, sonst geht nichts verloren.",
  "Wi-Fi": "WLAN",
  "Google Drive": "Google Drive",
  "Allow Attune to find your other device on this Wi-Fi (Android asks once).": "Erlaube Attune, dein anderes Gerät in diesem WLAN zu finden (Android fragt einmal).",
  "On the other device: Backup → Sync → Wi-Fi → Connect, and type:": "Auf dem anderen Gerät: Backup → Sync → WLAN → Verbinden, und gib ein:",
  "not on Wi-Fi": "nicht im WLAN",
  "Show a code on this device": "Einen Code auf diesem Gerät zeigen",
  "Or connect to the other device": "Oder mit dem anderen Gerät verbinden",
  "Make this device exactly like the other one (removes what the other doesn't have)": "Dieses Gerät genau wie das andere machen (entfernt, was das andere nicht hat)",
  "Connect and sync": "Verbinden und synchronisieren",
  "One file in your own Google Drive, in a hidden folder only Attune can open. It is locked with your sync passphrase on this device, so Google only stores noise.": "Eine Datei in deinem eigenen Google Drive, in einem versteckten Ordner, den nur Attune öffnen kann. Sie ist mit deiner Sync-Passphrase auf diesem Gerät verschlüsselt, Google speichert also nur Rauschen.",
  "Sync passphrase set on this device.": "Sync-Passphrase auf diesem Gerät festgelegt.",
  "Sync passphrase (10+ characters, the same on every device)": "Sync-Passphrase (10+ Zeichen, auf jedem Gerät dieselbe)",
  "Save passphrase": "Passphrase speichern",
  "Sync with Google Drive": "Mit Google Drive synchronisieren",
  "Last synced: {d}": "Zuletzt synchronisiert: {d}",
  "Wrong code or passphrase — nothing was changed.": "Falscher Code oder falsche Passphrase – nichts wurde geändert.",
  "Use at least 10 characters — the file lives in your Drive, so the passphrase is its only lock.": "Nimm mindestens 10 Zeichen – die Datei liegt in deinem Drive, die Passphrase ist ihr einziges Schloss.",
  "That passphrase is too easy to guess.": "Diese Passphrase ist zu leicht zu erraten.",
  "Only available in the Attune app": "Nur in der Attune-App verfügbar",
  "Google sync on the computer comes in the next update — use Wi-Fi with your phone for now.": "Google-Sync auf dem Computer kommt mit dem nächsten Update – nutze bis dahin WLAN mit deinem Handy.",
