  "No connections at all — Attune worked fully offline.": "Gar keine Verbindungen – Attune lief komplett offline.",
  "The AI ran on this device: none of your chats, notes, photos or money went to an AI company.": "Die KI lief auf diesem Gerät: Keiner deiner Chats, keine Notizen, Fotos oder Geldsachen gingen an ein KI-Unternehmen.",
  "{n} times": "{n}-mal",
  "{n} blocked": "{n} blockiert",
  "Only the place and the reason are kept, never what was sent. Counted on this device; it starts from the day you installed this update.": "Nur das Ziel und der Grund werden behalten, nie was gesendet wurde. Auf diesem Gerät gezählt; ab dem Tag, an dem du dieses Update installiert hast.",
