  "You pay": "Du zahlst",
  "Comes in": "Kommt rein",
  "Only a reminder — nothing happens by itself if you skip it.": "Nur eine Erinnerung – nichts passiert von selbst, wenn du sie überspringst.",
  "The free trial turns into a paid plan: {amount}.": "Der Gratis-Test wird zum bezahlten Tarif: {amount}.",
