  "Talk to Attune": "Mit Attune sprechen",
  "Your details — bookings and better answers": "Deine Angaben — Buchungen und passendere Antworten",
  "Private: everything here stays on this phone — Attune never uploads it, and its AI runs on the phone. Answers and agents use only your trip and daily-life details (never your passport, phone or email). A booking site gets your name, passport and phone only when you tap “Fill my details”.": "Privat: Alles hier bleibt auf diesem Telefon — Attune lädt es niemals hoch und die KI läuft direkt auf dem Gerät. Antworten und Agenten nutzen nur deine Reise- und Alltagsangaben (niemals Reisepass, Telefonnummer oder E-Mail). Eine Buchungsseite erhält deinen Namen, Pass und deine Nummer nur, wenn du auf „Meine Daten eintragen“ tippst.",
  "Use my details to make answers and agents fit me": "Meine Angaben nutzen, damit Antworten und Agenten zu mir passen",
  "Trips and hotels": "Reisen und Hotels",
  "Agents use these when your sentence doesn't say — e.g. a hotel watch looks for your stars by itself.": "Agenten nutzen diese Werte, wenn dein Satz nichts dazu sagt — z. B. sucht ein Hotel-Wächter automatisch nach deiner Sternekategorie.",
  "Daily life": "Alltag",
  "So Chat's answers fit you: food, health, your car, your work.": "Damit die Antworten im Chat zu dir passen: Essen, Gesundheit, dein Auto, deine Arbeit.",
  "For booking forms": "Für Buchungsformulare",
  "Typed into a booking site only when you tap “Fill my details”. Never used in answers.": "Wird nur dann in eine Buchungsseite eingetragen, wenn du auf „Meine Daten eintragen“ tippst. Wird niemals in Antworten verwendet.",
