  "You are on Free: unlimited answers, Money and Follow-ups. Pro adds agents that act for you, photo meals, Deal Check, Chat X-Ray, reports and exports.": "Du nutzt den Gratis-Tarif: unbegrenzte Antworten, Geld und Nachverfolgen. Pro ergänzt Agenten, die für dich handeln, Mahlzeiten per Foto, Angebots-Check, Chat-Röntgen, Berichte und Exporte.",
