  "Try Attune — a private AI on your phone for your money, meals and reminders. With my link you get a month of Pro free: {l}": "Probier Attune aus — eine private KI auf deinem Telefon für Geld, Mahlzeiten und Erinnerungen. Über meinen Link bekommst du einen Monat Pro gratis: {l}",
