  "Blood pressure, oxygen, sleep, resting heart rate and stress come in by themselves from your watch — nothing to type.": "Blutdruck, Blutsauerstoff, Schlaf, Ruhepuls und Stress kommen automatisch von deiner Uhr — ganz ohne Tippen.",
