  "One shopping list, who paid what for the house, and reminders for your parents — shared with your family's phones only, locked with a family code. No account, no server.": "Eine Einkaufsliste, wer was für den Haushalt bezahlt hat, und Erinnerungen für deine Eltern — nur mit den Telefonen deiner Familie geteilt, geschützt mit einem Familiencode. Kein Konto, kein Server.",
