  "Add the family below (a reminder for someone adds them too), or open a family file from their phone.": "Füge unten die Familie hinzu (eine Erinnerung für jemanden fügt die Person ebenfalls hinzu) oder öffne eine Familiendatei von ihrem Telefon.",
