  "e.g. the Kia": "z. B. der Kia",
  "You already have {n} — add what tells them apart (plumber, work…), and Attune will ask which one when it isn't clear.": "Du hast bereits {n} — füge hinzu, was sie unterscheidet (Klempner, Arbeit…), und Attune fragt nach, wenn es nicht eindeutig ist.",
  "Who / what is it to you": "Wer / was es für dich ist",
  "plumber, barber, work, my brother…": "Klempner, Friseur, Arbeit, mein Bruder…",
  "Other names you use (optional)": "Andere Namen, die du nutzt (optional)",
  "e.g. Hamada, الحلاق": "z. B. Hamada, الحلاق",
  "Remove the contact": "Kontakt entfernen",
  "Link a phone contact": "Telefonkontakt verknüpfen",
  "Optional — Attune keeps using your name for them.": "Optional — Attune verwendet weiterhin deinen Namen für die Person.",
  "Added — Attune links everything about {n} now": "Hinzugefügt — Attune verknüpft jetzt alles über {n}",
  "All people": "Alle Personen",
