  "Same person as…": "Dieselbe Person wie…",
  "Delete {n}'s card? Nothing else is deleted — only the link.": "Karte von {n} löschen? Es wird nichts anderes gelöscht — nur die Verknüpfung.",
  "One card now": "Jetzt in einer Karte zusammengeführt",
  "You paid": "Du hast gezahlt",
  "You got": "Du hast erhalten",
  "Everything about {n}": "Alles über {n}",
  "Nothing linked yet. When you write {n} (or another name of theirs) in Money, a note or a message, it shows here.": "Noch nichts verknüpft. Wenn du {n} (oder einen anderen Namen der Person) in Geld, einer Notiz oder einer Nachricht erwähnst, erscheint es hier.",
  "The people, places and things in your life. Attune links everything about each one — payments, notes, messages, follow-ups — and Chat answers from it. Two with the same name? It asks which one.": "Die Menschen, Orte und Dinge in deinem Leben. Attune verknüpft alles zu jedem Eintrag — Zahlungen, Notizen, Nachrichten, Nachverfolgungen — und der Chat antwortet daraus. Zwei mit demselben Namen? Attune fragt nach, wer gemeint ist.",
