  "Not a person": "Keine Person",
  "Search people": "Personen suchen",
  "No one yet": "Noch niemand eingetragen",
  "Add the people you deal with — your barber, the plumber, Ahmed from work — with your own name for each.": "Füge die Menschen hinzu, mit denen du zu tun hast — deinen Friseur, den Klempner, Ahmed von der Arbeit — jeweils mit deinem eigenen Namen für sie.",
  "From your notes": "Aus deinen Notizen",
