  "Each ruling with its evidence from the Qur'an and Sunnah and where it is taken from (Islamweb, Ibn Baz, al-Durar al-Saniyya). Your school in Zakāt settings decides where the schools differ.": "Jede Regel mit ihrem Beleg aus Koran und Sunna sowie der Quelle (Islamweb, Ibn Baz, al-Durar al-Saniyya). Deine gewählte Rechtsschule in den Zakat-Einstellungen entscheidet dort, wo sich die Schulen unterscheiden.",
