  "Ask me about your own money, e.g. “how much did I spend on food this week?” or “what did I earn this month?”": "Frag mich nach deinem eigenen Geld, z. B. „wie viel habe ich diese Woche für Essen ausgegeben?“ oder „was habe ich diesen Monat verdient?“",
