  "Payment pending — Pro turns on by itself as soon as Google confirms it.": "Zahlung ausstehend — Pro schaltet sich automatisch frei, sobald Google sie bestätigt.",
  "Google Play: {e}": "Google Play: {e}",
  "SHA-256": "SHA-256",
  "owner/repo:QUANT": "owner/repo:QUANT",
  "With more than one model installed: quick questions use the one already running; code, maths, reasoning and long reports move to your strongest model that runs smoothly here, and photos to one that sees. A switch takes 10–30 s.": "Wenn mehrere Modelle installiert sind: Kurze Fragen nutzen das bereits laufende Modell; Code, Mathe, Logik und lange Berichte wechseln zu deinem stärksten Modell, das hier flüssig läuft, und Fotos zu einem Modell mit Bilderkennung. Ein Wechsel dauert 10–30 Sek.",
  "The model itself never uses the network. The log lists every connection the app made or refused, host and reason only — the proof behind \\\"nothing leaves this phone\\\".": "Das Modell selbst nutzt niemals das Netzwerk. Das Protokoll listet jede hergestellte oder blockierte Verbindung der App nur mit Host und Grund auf — der Beweis hinter „nichts verlässt dieses Telefon“.",
  "When my salary arrives, put 20% in Savings": "Wenn mein Gehalt kommt, lege 20% in Ersparnisse",
