  "When a bonus arrives, put 50% in Savings": "Wenn ein Bonus kommt, lege 50% in Ersparnisse",
  "When InstaPay comes in, put 5% in the Car fund and tell me": "Wenn InstaPay eingeht, lege 5% in die Autokasse und gib mir Bescheid",
  "Gas": "Gas",
  "Mobile": "Mobilfunk",
  "I don't know your bills yet — after 3 months of electricity, water or internet in Money I'll tell you when each comes and how much.": "Ich kenne deine Rechnungen noch nicht — nach 3 Monaten mit Strom, Wasser oder Internet in Geld sage ich dir, wann jede Rechnung kommt und wie hoch sie etwa ist.",
