  "Customers who owe you more than 30 days get a polite WhatsApp statement from Money → Remind.": "Kunden, die seit mehr als 30 Tagen im Rückstand sind, erhalten über Geld → Erinnern eine höfliche Kontoübersicht per WhatsApp.",
