  "This system has no stock, balances, due dates or bookings yet. Ask the AI to add them, e.g. \\\"add a Payments table linked to Invoices\\\".": "Dieses System hat noch keinen Lagerbestand, keine Salden, Fälligkeiten oder Buchungen. Bitte die KI, sie hinzuzufügen, z. B. „füge eine Tabelle Zahlungen hinzu, die mit Rechnungen verknüpft ist“.",
  "What is your business, and what should the system be called?": "Was ist dein Geschäft und wie soll das System heißen?",
