  "Every time the books are opened with a PIN and something changed, an encrypted copy is kept on this phone (last 7 + one per month). It opens only with the PIN used that day.": "Jedes Mal, wenn die Buchhaltung mit einer PIN geöffnet und etwas geändert wird, bleibt eine verschlüsselte Kopie auf diesem Telefon gespeichert (die letzten 7 + eine pro Monat). Sie lässt sich nur mit der an jenem Tag genutzten PIN öffnen.",
