  "It renews by itself — you keep paying unless you cancel in time.": "Der Vertrag verlängert sich automatisch — du zahlst weiter, wenn du nicht rechtzeitig kündigst.",
  "Ask for renewal only by written agreement, or put the cancel-by date in your Deadline Radar.": "Bitte darum, dass eine Verlängerung nur schriftlich erfolgt, oder trage das Kündigungsdatum in deinen Fristen-Radar ein.",
  "Only one side can end it, or it can be ended without notice.": "Nur eine Seite kann kündigen, oder der Vertrag kann fristlos beendet werden.",
  "Ask that both sides can end it, with the same written notice (e.g. 30 days).": "Bitte darum, dass beide Seiten mit derselben schriftlichen Frist (z. B. 30 Tage) kündigen können.",
  "The other side can change the terms or the price on its own.": "Die andere Seite kann Bedingungen oder Preise im Alleingang ändern.",
  "Ask that changes need both signatures, and that you can leave without a penalty if you don't accept them.": "Bitte darum, dass Änderungen beide Unterschriften erfordern und du ohne Strafe aussteigen kannst, wenn du sie nicht akzeptierst.",
  "A penalty or forfeit clause — check the amount and that it applies to both sides.": "Eine Vertragsstrafen- oder Verfallsklausel — prüfe die Höhe und ob sie für beide Seiten gleichermaßen gilt.",
  "Ask for a cap (e.g. one month's value) and the same penalty for the other side.": "Bitte um eine Obergrenze (z. B. einen Monatswert) und dieselbe Vertragsstrafe für die Gegenseite.",
  "Money you pay here does not come back, even if the deal falls through.": "Geld, das du hier zahlst, wird nicht erstattet, selbst wenn das Geschäft platzt.",
  "Ask that it is refunded if the other side cancels or doesn't deliver.": "Bitte darum, dass es erstattet wird, falls die andere Seite absagt oder nicht liefert.",
  "You carry all the risk, with no limit.": "Du trägst das gesamte Risiko ohne Obergrenze.",
  "Ask for a limit (e.g. the contract's value) and to exclude what you can't control.": "Bitte um eine Haftungsgrenze (z. B. den Vertragswert) und darum, Dinge auszuschließen, die du nicht beeinflussen kannst.",
  "You may not work for a competitor after you leave — check how long and where.": "Du darfst nach deinem Ausscheiden nicht für die Konkurrenz arbeiten — prüfe für wie lange und wo.",
  "Ask for 6–12 months at most, one city or field, and pay for the time it applies.": "Bitte um höchstens 6–12 Monate, begrenzt auf eine Stadt oder Branche, sowie eine Karenzentschädigung für diese Zeit.",
  "Everything you make — even in your own time — would belong to them.": "Alles, was du entwickelst — selbst in deiner Freizeit — würde ihnen gehören.",
  "Ask to limit it to work done for them, in work time, with their tools.": "Bitte darum, das auf Arbeit zu begrenzen, die während der Arbeitszeit und mit deren Mitteln für sie erledigt wurde.",
  "Disputes go to arbitration or to another country's courts — this can be slow and expensive for you.": "Streitigkeiten gehen vor ein Schiedsgericht oder Gerichte in einem anderen Land — das kann für dich langwierig und teuer werden.",
  "Ask for the courts of your own city.": "Bitte um den Gerichtsstand deiner eigenen Stadt.",
  "You give up a right (to sue, to a refund, to object).": "Du verzichtest auf ein Recht (zu klagen, auf Rückerstattung oder auf Widerspruch).",
  "Ask to delete the waiver.": "Bitte darum, diesen Verzicht zu streichen.",
  "Sold as it is, with no guarantee — problems found later are yours.": "Verkauft wie gesehen, ohne Gewährleistung — später entdeckte Mängel trägst du selbst.",
  "Inspect it first (with an expert), or ask for a written guarantee period.": "Lass es vorher (mit einem Fachmann) prüfen oder bitte um eine schriftliche Garantiezeit.",
  "Secrecy that never ends.": "Geheimhaltung ohne zeitliches Ende.",
  "Ask for a fixed number of years (2–5 is common).": "Bitte um eine feste Anzahl von Jahren (üblich sind 2–5 Jahre).",
  "They may take money from your salary — check when and how much.": "Sie dürfen Beträge von deinem Gehalt einbehalten — prüfe wann und wie viel.",
  "Ask that deductions are only for set reasons, with a written notice and a cap.": "Bitte darum, dass Abzüge nur aus klar benannten Gründen, nach schriftlicher Ankündigung und bis zu einer Obergrenze erfolgen.",
  "Ask for no more than about 1–2 % a month, and a few days' grace.": "Bitte um höchstens ca. 1–2 % pro Monat sowie ein paar Tage Kulanzfrist.",
  "Ask for 5–10 % a year, written as a fixed schedule.": "Bitte um 5–10 % pro Jahr, festgelegt in einem klaren Stufenplan.",
  "Ask for 3 months.": "Bitte um 3 Monate.",
  "Before I sign, I'd like these changes:": "Vor meiner Unterschrift bitte ich um folgende Änderungen:",
  "Please also add:": "Bitte ergänzen Sie außerdem:",
  "Add your name": "Füge deinen Namen hinzu",
  "Add an email or a phone number so employers can reach you": "Füge eine E-Mail-Adresse oder Telefonnummer hinzu, damit Arbeitgeber dich erreichen können",
  "A 2–3 line summary at the top helps a recruiter decide quickly": "Eine kurze Zusammenfassung von 2–3 Zeilen ganz oben hilft Personalern, schnell zu entscheiden",
  "No experience yet — add your jobs, or projects if you are starting out": "Noch keine Berufserfahrung — füge deine bisherigen Stellen hinzu, oder Projekte, wenn du gerade erst anfängst",
  "Add your education or training": "Füge deine Ausbildung oder Weiterbildungen hinzu",
