  "Explain what you mean, e.g. “the price is 38,000 cash; 12,400 is the down payment”": "Erkläre kurz, was du meinst, z. B. „der Barpreis ist 38,000; 12,400 ist die Anzahlung“",
  "Read the offer again with this": "Angebot damit neu prüfen",
  "They want money before you see or receive it.": "Sie verlangen Geld, bevor du die Ware gesehen oder erhalten hast.",
  "Payment to a personal wallet or gift card — very hard to get back.": "Zahlung an eine private Wallet oder per Geschenkkarte — kaum zurückzuholen.",
  "They ask for a code sent to your phone — that is how accounts and wallets are stolen.": "Sie fragen nach einem Code, der an dein Telefon geschickt wurde — so werden Konten und Wallets gekapert.",
  "A prize you never entered for.": "Ein Gewinn bei einem Gewinnspiel, an dem du nie teilgenommen hast.",
  "Pressure to decide fast — a classic trick.": "Zeitdruck bei der Entscheidung — ein klassischer Trick.",
  "They move you off the platform, where you lose buyer protection.": "Sie locken dich von der Plattform weg, wo du den Käuferschutz verlierst.",
  "Guaranteed high profit — the sign of a Ponzi / investment scam.": "Garantierter hoher Gewinn — das typische Zeichen für ein Schneeballsystem oder Anlagebetrug.",
  "No warranty or returns.": "Keine Garantie und keine Rücknahme.",
  "It says copy / replica — not the original product.": "Dort steht Kopie / Replika — kein Originalprodukt.",
  "No real brand is named.": "Es wird keine echte Marke genannt.",
  "Says 0% interest — the real cost is checked below.": "Wirbt mit 0% Zinsen — die tatsächlichen Kosten werden unten geprüft.",
  "A seller with no ratings.": "Ein Verkäufer ohne Bewertungen.",
  "The installments add nothing over the cash price — a real 0%.": "Die Raten kosten keinen Aufpreis gegenüber dem Barpreis — echte 0%.",
  "Can I see it and pay on delivery (cash / card on receipt)?": "Kann ich es mir ansehen und erst bei Übergabe bezahlen (bar / mit Karte bei Erhalt)?",
  "What is the exact brand and model number? Can you send a photo of the label?": "Wie lauten Marke und genaue Modellnummer? Können Sie ein Foto vom Typenschild schicken?",
  "Is there an official warranty, and for how long? Invoice included?": "Gibt es eine offizielle Garantie und wie lange? Ist die Rechnung dabei?",
  "Can you do a better price? Others sell it for less.": "Geht beim Preis noch etwas? Andere bieten es günstiger an.",
  "What is the total I pay, all fees included? Is there an early-payment penalty?": "Was zahle ich insgesamt inklusive aller Gebühren? Gibt es eine Vorfälligkeitsentschädigung?",
  "Can I take it to an independent mechanic and check the papers (license, violations)?": "Kann ich den Wagen in einer unabhängigen Werkstatt prüfen lassen und die Papiere (Zulassung, Strafzettel) einsehen?",
  "Is the contract registered, and who pays the maintenance and utilities?": "Ist der Vertrag offiziell registriert und wer zahlt Instandhaltung sowie Nebenkosten?",
  "Can I get everything agreed in writing?": "Kann ich alle Vereinbarungen schriftlich bekommen?",
