  "Reading the photo took too long — name the food instead (e.g. “2 fried eggs and baladi bread”) and I'll log it at once": "Das Lesen des Fotos hat zu lange gedauert — nenne stattdessen das Essen (z. B. „2 Spiegeleier und Baladi-Brot“) und ich trage es sofort ein",
