  "Couldn't recognise the food in time — name it instead (e.g. “2 fried eggs and baladi bread”) or search it below": "Das Essen wurde nicht rechtzeitig erkannt — nenne es stattdessen (z. B. „2 Spiegeleier und Baladi-Brot“) oder suche es unten",
