  "This model can't read photos right now — name the food instead, e.g. “2 fried eggs and baladi bread”": "Dieses Modell kann gerade keine Fotos lesen — nenne stattdessen das Essen, z. B. „2 Spiegeleier und Baladi-Brot“",
  "This model can't read photos — get “Fast photo recognition” in My plan, or name the food, e.g. “2 fried eggs and baladi bread”": "Dieses Modell kann keine Fotos lesen — hol dir „Schnelle Fotoerkennung“ unter Mein Tarif oder nenne das Essen, z. B. „2 Spiegeleier und Baladi-Brot“",
