  "No sugar / salt data for today's foods — packaged products (barcode or search) carry them.": "Keine Zucker- / Salzangaben für die heutigen Lebensmittel — verpackte Produkte (per Barcode oder Suche) enthalten sie.",
  "Times by the sun's position (Egyptian General Authority angles), ±3 min — follow your local mosque's call.": "Gebetszeiten nach Sonnenstand (Winkel der ägyptischen Vermessungsbehörde), ±3 Min. — richte dich nach dem Gebetsruf deiner Moschee vor Ort.",
