  "US Navy method: waist at the navel (women: narrowest), neck below the Adam's apple — ±3 %. The trend matters more than one number.": "US-Navy-Methode: Bauchumfang am Nabel (Frauen: schmalste Stelle), Hals unterhalb des Kehlkopfs — ±3 %. Der Trend zählt mehr als ein einzelner Wert.",
  "Drink a glass of water": "Ein Glas Wasser trinken",
