  "Tell Attune whose message you are waiting for — on WhatsApp, Gmail, SMS or any email app — and it tells you the moment it arrives. Checked on this phone; SMS can be switched off below.": "Sag Attune, auf wessen Nachricht du wartest — auf WhatsApp, Gmail, SMS oder in jeder E-Mail-App — und es sagt dir Bescheid, sobald sie ankommt. Geprüft auf diesem Telefon; SMS kannst du unten ausschalten.",
  "Numbers in the photo, read by the phone: {n} — check them.": "Zahlen im Foto, vom Telefon gelesen: {n} — bitte prüfen.",
  "Was due {d}": "War fällig am {d}",
  "Due {d} · in {n} days": "Fällig am {d} · in {n} Tagen",
  "Due date (optional)": "Fälligkeitsdatum (optional)",
  "What it should always know about this work": "Was es über diese Arbeit immer wissen soll",
  "Delete this project? Its chats stay in Chat.": "Dieses Projekt löschen? Seine Chats bleiben im Chat.",
  "Pages, documents and programs Attune made in this work. Ask for one, then tap Save on its card — it is kept here.": "Seiten, Dokumente und Programme, die Attune für diese Arbeit erstellt hat. Bitte um eines und tippe auf seiner Karte auf Speichern – es bleibt hier.",
  "Nothing saved here yet.": "Hier ist noch nichts gespeichert.",
  "Questions this work asks again and again. Run one with a tap — the ones whose time has come are marked.": "Fragen, die diese Arbeit immer wieder stellt. Starte eine mit einem Tippen – die fälligen sind markiert.",
  "No repeats yet.": "Noch keine Wiederholungen.",
