  "Close this Zakāt year? Its payments become one closed year with a certificate, and a new Zakāt year starts today.": "Dieses Zakāt-Jahr abschließen? Seine Zahlungen werden ein abgeschlossenes Jahr mit Bescheinigung, und heute beginnt ein neues Zakāt-Jahr.",
  "Closed — the certificate is under Closed years": "Abgeschlossen — die Bescheinigung steht unter Abgeschlossene Jahre",
  "Ramadan is here — Zakāt al-Fiṭr is due before the Eid prayer": "Es ist Ramadan — die Zakāt al-Fiṭr ist vor dem Eid-Gebet fällig",
  "One question before your Zakāt is worked out": "Eine Frage, bevor deine Zakāt berechnet wird",
  "You owe {a}. Scholars differ on whether a debt is taken off the wealth you pay Zakāt on. It is your choice — until you choose, nothing is taken off.": "Du schuldest {a}. Die Gelehrten sind uneins, ob eine Schuld vom Vermögen abgezogen wird, auf das du Zakāt zahlst. Du entscheidest — bis dahin wird nichts abgezogen.",
  "Below the niṣāb": "Unter dem Niṣāb",
  "due {d}": "fällig {d}",
  "Zakāt {a} · 2.5% of {b}": "Zakāt {a} · 2,5 % von {b}",
  "Niṣāb {a}": "Niṣāb {a}",
  "{n} g of {m} g": "{n} g von {m} g",
  "Livestock Zakāt": "Zakāt auf Vieh",
  "{n} head": "{n} Stück",
  "Not free-grazing — no Zakāt on them": "Nicht frei weidend — keine Zakāt darauf",
  "Below the niṣāb ({n} head)": "Unter dem Niṣāb ({n} Stück)",
  "Due now: {x}": "Jetzt fällig: {x}",
  "Its ḥawl is running — due {d} (in {n} days)": "Sein Ḥawl läuft — fällig {d} (in {n} Tagen)",
  "Paid vs due": "Bezahlt und fällig",
  "Paid so far": "Bisher bezahlt",
  "Still to pay": "Noch zu zahlen",
  "Fully paid — may Allah accept it": "Vollständig bezahlt — möge Allah es annehmen",
  "Close this Zakāt year": "Dieses Zakāt-Jahr abschließen",
  "Closed years": "Abgeschlossene Jahre",
  "No closed year yet — when you finish paying a year's Zakāt, close it here and keep its certificate.": "Noch kein abgeschlossenes Jahr — wenn du die Zakāt eines Jahres bezahlt hast, schließe es hier ab und behalte die Bescheinigung.",
  "An estimate to guide you. It uses the gold nisab (85g) and 2.5% on cash, gold, silver and money owed to you — not your home, car, or work equipment. Rulings on debts and on dropping below nisab during the year differ between scholars; confirm your case with a trusted scholar.": "Eine Schätzung zur Orientierung. Sie nutzt den Gold-Niṣāb (85 g) und 2,5 % auf Bargeld, Gold, Silber und Geld, das man dir schuldet — nicht auf dein Haus, Auto oder Arbeitsgerät. Die Urteile zu Schulden und zum Unterschreiten des Niṣāb im Jahr sind unter Gelehrten verschieden; prüfe deinen Fall mit einem vertrauenswürdigen Gelehrten.",
  "Nothing yet today — tell the box what you spent or need to remember.": "Heute noch nichts — sag dem Feld, was du ausgegeben hast oder woran du denken musst.",
  "These offers were read before Attune could read the hotel names and photos — tap Check now to get them.": "Diese Angebote wurden gelesen, bevor Attune Hotelnamen und Fotos lesen konnte — tippe auf Jetzt prüfen, um sie zu bekommen.",
