  "Have a nice trip! Make a travel list once — “make my travel checklist: passport, charger…” — and it comes back before every trip.": "Gute Reise! Mach einmal eine Reiseliste — „mach meine Reise-Checkliste: Pass, Ladegerät…“ — und sie kommt vor jeder Reise zurück.",
