  "Help me find a job: tailor my CV, write cover letters and prepare me for interviews.": "Hilf mir, einen Job zu finden: passe meinen Lebenslauf an, schreibe Anschreiben und bereite mich auf Gespräche vor.",
  "Update my CV": "Lebenslauf aktualisieren",
  "List 10 companies": "10 Firmen auflisten",
