  "A file locked with a family code you agree on, sent through WhatsApp or any app. No account, no server — only the people with the code can open it.": "Eine Datei, gesperrt mit einem vereinbarten Familiencode, verschickt per WhatsApp oder jeder App. Kein Konto, kein Server — nur wer den Code hat, kann sie öffnen.",
