  "Open the file": "Datei öffnen",
  "Attune reads the notifications your apps show (WhatsApp, SMS, email, Instagram, YouTube…) to plan your day: who wrote, what someone asked for at a time, what arrives today.": "Attune liest die Benachrichtigungen deiner Apps (WhatsApp, SMS, E-Mail, Instagram, YouTube…), um deinen Tag zu planen: wer geschrieben hat, was jemand für eine Uhrzeit wollte, was heute ankommt.",
  "They are read and kept on this phone only. Nothing is sent to us or to anyone. No account, no cloud.": "Sie werden nur auf diesem Handy gelesen und gespeichert. Nichts geht an uns oder an irgendwen. Kein Konto, keine Cloud.",
  "You choose which apps count (Settings → Your day), and you can forget everything kept at any time.": "Du wählst, welche Apps zählen (Einstellungen → Dein Tag), und kannst jederzeit alles Gespeicherte löschen.",
  "Is this a scam?": "Ist das Betrug?",
  "Paste a message, an offer or a link — or pick a screenshot. Checked on this phone; nothing is sent anywhere.": "Füge eine Nachricht, ein Angebot oder einen Link ein — oder wähle einen Screenshot. Geprüft auf diesem Handy; nichts wird gesendet.",
  "e.g. “You won 5,000 EGP from InstaPay — send the code you'll receive…”": "z. B. „Du hast 5.000 EGP von InstaPay gewonnen — sende den Code, den du bekommst…“",
  "No text found in the picture": "Kein Text im Bild gefunden",
