  "Ramadan mode": "Ramadan-Modus",
  "Only during Ramadan: the countdown to iftar on Home and a day planned around the fast.": "Nur im Ramadan: der Countdown bis zum Iftar auf der Startseite und ein Tag um das Fasten geplant.",
