  "Safe to spend today: {a}": "Heute verfügbar: {a}",
  "Nothing due today — open Attune to add a to-do": "Heute nichts fällig — öffne Attune, um ein To-do hinzuzufügen",
  "A list": "Eine Liste",
  "In Attune: To-dos & lists → open a list → Pin to the widget": "In Attune: To-dos & Listen → eine Liste öffnen → Ans Widget heften",
  "Every box is ticked": "Alles abgehakt",
  "This update is from another share.": "Dieses Update stammt aus einer anderen Freigabe.",
  "The ledger didn't take it": "Das Kassenbuch hat es nicht angenommen",
  "Open Money first": "Öffne zuerst Geld",
  "This isn't a Money share.": "Das ist keine Geld-Freigabedatei.",
  "They want money before you see or receive anything.": "Sie wollen Geld, bevor du etwas siehst oder bekommst.",
  "Payment to a personal wallet or a gift card — very hard to get back.": "Zahlung auf ein privates Wallet oder eine Geschenkkarte — kaum zurückzubekommen.",
  "Guaranteed high profit — the sign of an investment scam.": "Garantierter hoher Gewinn — Zeichen für Anlagebetrug.",
  "“Your account will be blocked” — banks and wallets never ask you to fix it through a message.": "„Dein Konto wird gesperrt“ — Banken und Wallets verlangen nie, das per Nachricht zu klären.",
  "They ask for your card number, PIN or password — never give these to anyone.": "Sie fragen nach Kartennummer, PIN oder Passwort — gib das niemandem.",
  "“This is my new number” followed by a request — call the person on their old number first.": "„Das ist meine neue Nummer“ und dann eine Bitte — ruf die Person zuerst unter der alten Nummer an.",
  "A parcel “held” until you pay a small fee — a common trick to get your card details.": "Ein „zurückgehaltenes“ Paket, bis du eine kleine Gebühr zahlst — ein bekannter Trick für deine Kartendaten.",
  "Easy money for liking videos or small tasks — these end with you paying “to unlock” your earnings.": "Leichtes Geld fürs Liken von Videos oder kleine Aufgaben — am Ende sollst du zahlen, um deinen Verdienst „freizuschalten“.",
  "A link that asks you to log in or confirm something.": "Ein Link, der dich zum Anmelden oder Bestätigen auffordert.",
  "The link says “{b}” but goes to {l} — not the real site.": "Der Link nennt „{b}“, führt aber zu {l} — nicht die echte Seite.",
  "Your day from your notifications (optional)": "Dein Tag aus deinen Benachrichtigungen (optional)",
  "With Notification access on, Attune reads the notifications kept on the device to plan your day: who wrote to you today, what someone asked for at a time (shown as a reminder you can add), what arrives today, and a count of other apps (Instagram, YouTube…). This happens on the device, by code; nothing is sent anywhere. Choose which apps count, or switch it off, in Settings → Your day.": "Mit eingeschaltetem Benachrichtigungszugriff liest Attune die auf dem Gerät gespeicherten Benachrichtigungen, um deinen Tag zu planen: wer dir heute geschrieben hat, was jemand für eine Uhrzeit wollte (als Erinnerung zum Hinzufügen angezeigt), was heute ankommt, und wie viele Benachrichtigungen andere Apps hatten (Instagram, YouTube…). Das passiert auf dem Gerät, per Code; nichts wird irgendwohin gesendet. Wähle die Apps oder schalte es aus unter Einstellungen → Dein Tag.",
  "Sharing Money with family (optional)": "Geld mit der Familie teilen (optional)",
  "If you start a family share, Attune makes one file with only what you chose (some accounts, or all of Money), locked with a family code you agree on (AES-256), and hands it to the app you pick (WhatsApp, email…) to send. Attune has no server and never sees it; only people with the code can open it. Zakat records are never shared. Stop any time in Money → More → Share with family.": "Wenn du eine Familienfreigabe startest, erstellt Attune eine Datei nur mit dem, was du gewählt hast (bestimmte Konten oder das ganze Geld), gesperrt mit einem vereinbarten Familiencode (AES-256), und übergibt sie der App deiner Wahl (WhatsApp, E-Mail…) zum Versenden. Attune hat keinen Server und sieht sie nie; nur wer den Code hat, kann sie öffnen. Zakat-Einträge werden nie geteilt. Beenden jederzeit unter Geld → Mehr → Mit der Familie teilen.",
